def check_solution(a, b):
    # Original equation: a^2 + 2*3^b = a*(2^(b+1) - 1)
    lhs = a**2 + 2 * (3**b)
    rhs = a * (2**(b+1) - 1)
    return lhs == rhs, lhs, rhs

solutions = [(9, 3), (6, 3), (9, 5), (54, 5)]
results = {}

for a, b in solutions:
    is_valid, lhs, rhs = check_solution(a, b)
    results[(a, b)] = {
        "valid": is_valid,
        "LHS": lhs,
        "RHS": rhs
    }

for sol, res in results.items():
    print(f"Solution {sol}: Valid = {res['valid']}. LHS = {res['LHS']}, RHS = {res['RHS']}")
